		gaSet('dimension2', uId);
		gaSet('hasFb', !!loggedUser.fbId);
		gaSet('dimension3', !!loggedUser.fbId);
		gaSet('joinWeek', getWeekNumber(genDate));
		gaSet('dimension4', getWeekNumber(genDate));
